from collections import deque

from graph import closure


def waves(graph, targets, changed, cached):
    scope = closure(graph, targets)

    # Validate the whole scope first (including cached jobs).
    missing = [n for n in scope if n not in graph]
    if missing:
        raise ValueError("missing: " + min(missing))

    # Topological order via Kahn's algorithm; also detects cycles.
    reverse = {n: [] for n in scope}
    in_deg = {}
    for n in scope:
        prereqs = graph.get(n, ())
        deg = 0
        for p in prereqs:
            if p in scope:
                deg += 1
                reverse[p].append(n)
        in_deg[n] = deg
    q = deque([n for n in scope if in_deg[n] == 0])
    order = []
    while q:
        n = q.popleft()
        order.append(n)
        for m in reverse[n]:
            in_deg[m] -= 1
            if in_deg[m] == 0:
                q.append(m)
    if len(order) < len(scope):
        raise ValueError("cycle")

    changed_set = set(changed)
    cached_set = set(cached)

    needs = {}
    wave = {}
    for n in order:
        prereqs = graph.get(n, ())
        needs[n] = (
            n in changed_set
            or n not in cached_set
            or any(needs[p] for p in prereqs)
        )
        if needs[n]:
            max_w = -1
            for p in prereqs:
                if needs[p]:
                    max_w = max(max_w, wave[p])
            wave[n] = max_w + 1

    if not wave:
        return []
    max_wave = max(wave.values())
    result = [[] for _ in range(max_wave + 1)]
    for n, w in wave.items():
        result[w].append(n)
    return [sorted(w) for w in result]
